"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[383],{246(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/intro","label":"Welcome to the Study of Physical AI","docId":"intro","unlisted":false},{"type":"category","label":"Module 1: Foundations","items":[{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/introduction/physical-ai-overview","label":"Physical AI Overview","docId":"introduction/physical-ai-overview","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/foundations/embodied-intelligence","label":"Embodied Intelligence","docId":"foundations/embodied-intelligence","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/foundations/humanoid-robots","label":"Humanoid Robots","docId":"foundations/humanoid-robots","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 2: The Robotic Nervous System","items":[{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/ros2/getting-started-with-ros2","label":"Getting Started with ROS 2","docId":"ros2/getting-started-with-ros2","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/ros2/ros2-architecture","label":"ROS 2 Architecture","docId":"ros2/ros2-architecture","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/ros2/nodes-topics-services","label":"Nodes, Topics, Services, and Actions","docId":"ros2/nodes-topics-services","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 3: Simulation and Digital Twins","items":[{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/digital-twins/the-role-of-simulation","label":"The Role of Simulation and Digital Twins","docId":"digital-twins/the-role-of-simulation","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/digital-twins/gazebo","label":"Gazebo: The Robotics Simulator","docId":"digital-twins/gazebo","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/digital-twins/unity","label":"Unity for Robotics Simulation","docId":"digital-twins/unity","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 4: Perception and AI","items":[{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/nvidia-isaac/the-ai-brain-for-robots","label":"NVIDIA Isaac: The AI Brain for Robots","docId":"nvidia-isaac/the-ai-brain-for-robots","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/nvidia-isaac/perception","label":"Perception: Giving Robots Sight and Understanding","docId":"nvidia-isaac/perception","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/nvidia-isaac/sim-to-real","label":"Sim-to-Real: Bridging the Reality Gap with NVIDIA Isaac","docId":"nvidia-isaac/sim-to-real","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 5: Advanced Intelligence","items":[{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/vla/introduction-to-vla","label":"Introduction to Vision-Language-Action (VLA) Models","docId":"vla/introduction-to-vla","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/vla/vision-language-action","label":"Vision-Language-Action (VLA): Towards General-Purpose Robot Intelligence","docId":"vla/vision-language-action","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/vla/llms-for-robotics","label":"Large Language Models (LLMs) for Robotics","docId":"vla/llms-for-robotics","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 6: Capstone Project","items":[{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/capstone/project-overview","label":"Capstone Project: Autonomous Humanoid Overview","docId":"capstone/project-overview","unlisted":false},{"type":"link","href":"/Physical-Ai-Humanoid-Robotics-Textbook/capstone/autonomous-humanoid","label":"Autonomous Humanoid: Bringing It All Together","docId":"capstone/autonomous-humanoid","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"capstone/autonomous-humanoid":{"id":"capstone/autonomous-humanoid","title":"Autonomous Humanoid: Bringing It All Together","description":"The dream of autonomous humanoids\u2014robots capable of perceiving, understanding, reasoning, and acting like humans in human environments\u2014represents the ultimate challenge and triumph of Physical AI. This section synthesizes the various technological threads woven through this textbook, envisioning the integrated systems required for a truly autonomous humanoid. It is the culmination of our journey, illustrating how ROS 2, advanced simulation, NVIDIA Isaac\'s AI capabilities, and Vision-Language-Action (VLA) models converge to create intelligent, embodied agents.","sidebar":"tutorialSidebar"},"capstone/project-overview":{"id":"capstone/project-overview","title":"Capstone Project: Autonomous Humanoid Overview","description":"This capstone project serves as the culminating experience for this textbook, integrating all the knowledge and skills acquired throughout the previous modules. Your journey through ROS 2, Digital Twin simulations, NVIDIA Isaac\'s AI capabilities, and Vision-Language-Action (VLA) models has prepared you to tackle the formidable challenge of creating an autonomous humanoid robot. This project is designed to bridge theory with practice, providing a hands-on opportunity to apply state-of-the-art AI and robotics techniques to a complex, real-world-inspired problem.","sidebar":"tutorialSidebar"},"digital-twins/gazebo":{"id":"digital-twins/gazebo","title":"Gazebo: The Robotics Simulator","description":"Gazebo is an open-source 3D robotics simulator that allows developers to accurately and efficiently test algorithms, design robots, and perform regression testing in a virtual environment. It provides robust physics simulation, high-quality graphics, and programmatic interfaces, making it a cornerstone tool for researchers and engineers in Physical AI.","sidebar":"tutorialSidebar"},"digital-twins/the-role-of-simulation":{"id":"digital-twins/the-role-of-simulation","title":"The Role of Simulation and Digital Twins","description":"In Physical AI and humanoid robotics, developing and refining intelligent robotic systems demands safe and efficient environments. Simulation and digital twins are indispensable, offering a virtual proving ground for rapid iteration, risk mitigation, and scalable development beyond physical hardware limitations.","sidebar":"tutorialSidebar"},"digital-twins/unity":{"id":"digital-twins/unity","title":"Unity for Robotics Simulation","description":"Unity, a leading game development engine, is increasingly adopted for robotics simulation, offering high visual fidelity and a rich ecosystem. This addresses the need for realistic visual environments, crucial for training vision-based AI, complementing traditional physics simulators like Gazebo.","sidebar":"tutorialSidebar"},"foundations/embodied-intelligence":{"id":"foundations/embodied-intelligence","title":"Embodied Intelligence","description":"Embodied intelligence posits that intelligence arises from the dynamic interplay between an agent\'s brain, physical body, and its environment, departing from the traditional \\"brain in a vat\\" AI model.","sidebar":"tutorialSidebar"},"foundations/humanoid-robots":{"id":"foundations/humanoid-robots","title":"Humanoid Robots","description":"A humanoid robot is a robotic platform designed to mimic the human body, typically including a torso, head, two arms, and two legs. This form factor is a strategic choice for creating general-purpose robots that seamlessly integrate into human environments.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Welcome to the Study of Physical AI","description":"This textbook is your guide into the rapidly advancing world of Physical AI, a field dedicated to embedding intelligence not in digital spaces, but in the physical world. We are embarking on a journey to understand how to create systems that can perceive, reason, and act in complex, real-world environments.","sidebar":"tutorialSidebar"},"introduction/physical-ai-overview":{"id":"introduction/physical-ai-overview","title":"Physical AI Overview","description":"Physical Artificial Intelligence (Physical AI) represents a paradigm shift in the field of AI. It is the discipline of creating intelligent agents that can perceive, reason, and act within the physical world. Unlike traditional AI, which often exists in a purely digital form, Physical AI is fundamentally concerned with embodiment\u2014the integration of intelligence into a physical form that can interact with its environment.","sidebar":"tutorialSidebar"},"nvidia-isaac/perception":{"id":"nvidia-isaac/perception","title":"Perception: Giving Robots Sight and Understanding","description":"Perception is a cornerstone for autonomous and intelligent robots. It\'s how a robot collects, processes, and interprets sensory data to understand its environment. Accurate perception is vital for safe navigation, effective object manipulation, and intelligent human interaction, serving as the critical first step in the \\"sense-plan-act\\" cycle of physical systems.","sidebar":"tutorialSidebar"},"nvidia-isaac/sim-to-real":{"id":"nvidia-isaac/sim-to-real","title":"Sim-to-Real: Bridging the Reality Gap with NVIDIA Isaac","description":"Sim-to-real is the critical process of transferring knowledge from simulation to physical robots. Bridging the sim-to-real gap\u2014the disparity between simulated and real-world performance\u2014is a paramount challenge in AI-driven robotics. NVIDIA Isaac is specifically designed to tackle this, optimizing simulated training and accelerating real-world deployment.","sidebar":"tutorialSidebar"},"nvidia-isaac/the-ai-brain-for-robots":{"id":"nvidia-isaac/the-ai-brain-for-robots","title":"NVIDIA Isaac: The AI Brain for Robots","description":"As Physical AI advances, robots need sophisticated \\"brains\\" for real-time perception, intelligent decision-making, and adaptive control. NVIDIA Isaac is a pivotal, comprehensive ecosystem integrating hardware, software, and simulation to accelerate AI-powered robot development and deployment. It enables AI-native robots, where AI is a fundamental, integrated component.","sidebar":"tutorialSidebar"},"ros2/getting-started-with-ros2":{"id":"ros2/getting-started-with-ros2","title":"Getting Started with ROS 2","description":"The Robot Operating System (ROS) has emerged as the de-facto standard for robotics middleware, providing a flexible framework for writing robot software. ROS 2, its successor, is a significant evolution, designed to address the demanding requirements of modern robotics, including real-time control, multi-robot systems, and production-grade deployments. This module introduces ROS 2 as the foundational software architecture that enables complex robotic systems to function cohesively.","sidebar":"tutorialSidebar"},"ros2/nodes-topics-services":{"id":"ros2/nodes-topics-services","title":"Nodes, Topics, Services, and Actions","description":"In ROS 2, the true power of its distributed architecture is realized through a set of well-defined communication mechanisms. These mechanisms allow independent processes (nodes) to interact, exchange data, and coordinate actions, forming the complex behaviors of a robotic system. Understanding these core concepts\u2014Nodes, Topics, Services, and Actions\u2014is fundamental to developing robust ROS 2 applications.","sidebar":"tutorialSidebar"},"ros2/ros2-architecture":{"id":"ros2/ros2-architecture","title":"ROS 2 Architecture","description":"ROS 2\'s distributed architecture is crucial for building complex, modular, and scalable robotic systems, abstracting networking and concurrency. Understanding this structure is key to robust robot software development.","sidebar":"tutorialSidebar"},"tutorial-basics/congratulations":{"id":"tutorial-basics/congratulations","title":"Congratulations!","description":"You have just learned the basics of Docusaurus and made some changes to the initial template."},"tutorial-basics/create-a-blog-post":{"id":"tutorial-basics/create-a-blog-post","title":"Create a Blog Post","description":"Docusaurus creates a page for each blog post, but also a blog index page, a tag system, an RSS feed..."},"tutorial-basics/create-a-document":{"id":"tutorial-basics/create-a-document","title":"Create a Document","description":"Documents are groups of pages connected through:"},"tutorial-basics/create-a-page":{"id":"tutorial-basics/create-a-page","title":"Create a Page","description":"Add Markdown or React files to src/pages to create a standalone page:"},"tutorial-basics/deploy-your-site":{"id":"tutorial-basics/deploy-your-site","title":"Deploy your site","description":"Docusaurus is a static-site-generator (also called Jamstack)."},"tutorial-basics/markdown-features":{"id":"tutorial-basics/markdown-features","title":"Markdown Features","description":"Docusaurus supports Markdown and a few additional features."},"tutorial-extras/manage-docs-versions":{"id":"tutorial-extras/manage-docs-versions","title":"Manage Docs Versions","description":"Docusaurus can manage multiple versions of your docs."},"tutorial-extras/translate-your-site":{"id":"tutorial-extras/translate-your-site","title":"Translate your site","description":"Let\'s translate docs/intro.md to French."},"vla/introduction-to-vla":{"id":"vla/introduction-to-vla","title":"Introduction to Vision-Language-Action (VLA) Models","description":"The aspiration for truly intelligent robots that can understand and execute human commands in complex, unstructured environments has long been a driving force in AI and robotics. Traditional robotic systems often require meticulous programming for each new task and struggle to generalize to novel situations, necessitating a paradigm shift. The advent of large language models (LLMs) and advanced visual perception has paved the way for a revolutionary paradigm: Vision-Language-Action (VLA) models. VLA models aim to bridge the gap between high-level human intent expressed in natural language and the low-level physical actions required for robots to operate effectively in the real world, thereby unlocking new frontiers in robotic autonomy and human-robot collaboration.","sidebar":"tutorialSidebar"},"vla/llms-for-robotics":{"id":"vla/llms-for-robotics","title":"Large Language Models (LLMs) for Robotics","description":"Large Language Models (LLMs) have transformed natural language processing, demonstrating unprecedented capabilities in understanding, generating, and reasoning with human language. Their emergent abilities in common sense reasoning and knowledge synthesis make them increasingly vital for intelligent robotic systems. Integrating LLMs into robotics elevates robot control, enabling intuitive human-robot interaction and flexible task execution.","sidebar":"tutorialSidebar"},"vla/vision-language-action":{"id":"vla/vision-language-action","title":"Vision-Language-Action (VLA): Towards General-Purpose Robot Intelligence","description":"This section explores Vision-Language-Action (VLA) models, a powerful paradigm for robots leveraging visual perception and linguistic understanding to execute complex tasks. VLA models mark a significant step towards creating general-purpose robots operating flexibly and intuitively in dynamic, human-centric environments.","sidebar":"tutorialSidebar"}}}}')}}]);